12	export class RuntimeManager {
13	  private initialHealthyCheck = new Deferred<void>();
14	  private config: RuntimeConfig;
15	  private lazy: boolean;
16	
17	  constructor(config: RuntimeConfig, lazy = false) {
18	    this.config = config;
19	    this.lazy = lazy;
20	    // Validate the URL on construction
21	    try {
22	      new URL(this.config.url);
23	    } catch (error) {
24	      throw new Error(
25	        `Invalid runtime URL: ${this.config.url}. ${error instanceof Error ? error.message : "Unknown error"}`,
26	        { cause: error },
27	      );
28	    }
29	
30	    if (!this.lazy) {
31	      this.init();
32	    }
33	  }
34	
35	  get isLazy(): boolean {
36	    return this.lazy;
37	  }
38	
39	  get httpURL(): URL {
40	    return new URL(this.config.url);
41	  }
42	
43	  get isSameOrigin(): boolean {
44	    return this.httpURL.origin === window.location.origin;
45	  }
46	
47	  /**
48	   * The base URL of the runtime.
49	   */
50	  formatHttpURL(
51	    path?: string,
52	    searchParams?: URLSearchParams,
53	    restrictToKnownQueryParams = true,
54	  ): URL {
55	    if (!path) {
56	      path = "";
57	    }
58	    // URL may be something like "http://localhost:8000?auth=123"
59	    const baseUrl = this.httpURL;
60	    const currentParams = new URLSearchParams(window.location.search);
61	    // Copy over search params if provided
62	    if (searchParams) {
63	      for (const [key, value] of searchParams.entries()) {
64	        baseUrl.searchParams.set(key, value);
65	      }
66	    }
67	
68	    for (const [key, value] of currentParams.entries()) {
69	      if (
70	        restrictToKnownQueryParams &&
71	        !Object.values(KnownQueryParams).includes(key)
72	      ) {
73	        continue;
74	      }
75	      baseUrl.searchParams.set(key, value);
76	    }
77	
78	    const cleanPath = baseUrl.pathname.replace(/\/$/, "");
79	    baseUrl.pathname = `${cleanPath}/${path.replace(/^\//, "")}`;
80	    baseUrl.hash = "";
81	    return baseUrl;
82	  }
83	
84	  formatWsURL(path: string, searchParams?: URLSearchParams): URL {
85	    // We don't restrict to known query parameters, since mo.query_params()
86	    // can accept arbitrary parameters.
87	    const url = this.formatHttpURL(
88	      path,
89	      searchParams,
90	      /* restrictToKnownQueryParams =*/ false,
91	    );
92	
93	    // For cross-origin runtimes, pass the auth token as a query parameter.
94	    // WebSocket connections cannot send custom headers (no Authorization
95	    // header), and cross-origin cookies are blocked by browsers, so the
96	    // access_token query param is the only way to authenticate.
97	    if (!this.isSameOrigin && this.config.authToken) {
98	      url.searchParams.set(KnownQueryParams.accessToken, this.config.authToken);
99	    }
100	
101	    return asWsUrl(url.toString());
102	  }
103	
104	  /**
105	   * The WebSocket URL of the runtime.
106	   */
107	  getWsURL(sessionId: SessionId): URL {
108	    const baseUrl = new URL(this.config.url);
109	    const searchParams = new URLSearchParams(baseUrl.search);
110	
111	    // Merge in current page's query parameters
112	    const currentParams = new URLSearchParams(window.location.search);
113	    currentParams.forEach((value, key) => {
114	      // Don't override base URL params
115	      if (!searchParams.has(key)) {
116	        searchParams.set(key, value);
117	      }
118	    });
119	
120	    searchParams.set(KnownQueryParams.sessionId, sessionId);
121	    return this.formatWsURL("/ws", searchParams);
122	  }
123	
124	  /**
125	   * The WebSocket Sync URL of the runtime, for real-time updates.
126	   */
127	  getWsSyncURL(sessionId: SessionId): URL {
128	    const baseUrl = new URL(this.config.url);
129	    const searchParams = new URLSearchParams(baseUrl.search);
130	
131	    // Merge in current page's query parameters
132	    const currentParams = new URLSearchParams(window.location.search);
133	    currentParams.forEach((value, key) => {
134	      // Don't override base URL params
135	      if (!searchParams.has(key)) {
136	        searchParams.set(key, value);
137	      }
138	    });
139	
140	    searchParams.set(KnownQueryParams.sessionId, sessionId);
141	    return this.formatWsURL("/ws_sync", searchParams);
142	  }
143	
144	  /**
145	   * The WebSocket URL of the terminal.
146	   */
147	  getTerminalWsURL(): URL {
148	    return this.formatWsURL("/terminal/ws");
149	  }
150	
151	  /**
152	   * The URL of the copilot server.
153	   */
154	  getLSPURL(lsp: "pylsp" | "basedpyright" | "copilot" | "ty" | "pyrefly"): URL {
155	    if (lsp === "copilot") {
156	      // For copilot, strip all query parameters except the auth token.
157	      // Copilot doesn't understand arbitrary query params, but we still
158	      // need access_token for cross-origin authentication.
159	      const url = this.formatWsURL(`/lsp/${lsp}`);
160	      const accessToken = url.searchParams.get(KnownQueryParams.accessToken);
161	      url.search = "";
162	      if (accessToken) {
163	        url.searchParams.set(KnownQueryParams.accessToken, accessToken);
164	      }
165	      return url;
166	    }
167	    return this.formatWsURL(`/lsp/${lsp}`);
168	  }
169	
170	  getAiURL(path: "completion" | "chat"): URL {
171	    return this.formatHttpURL(`/api/ai/${path}`);
172	  }
173	
174	  /**
175	   * The URL of the health check endpoint.
176	   */
177	  healthURL(): URL {
178	    return this.formatHttpURL("/health");
179	  }
180	
181	  async isHealthy(): Promise<boolean> {
182	    // Always healthy if WASM, Islands, or a static notebook (no server)
183	    if (isWasm() || isIslands() || isStaticNotebook()) {
184	      return true;
185	    }
186	
187	    try {
188	      const response = await fetch(this.healthURL().toString());
189	      // If there is a redirect, update the URL in the config
190	      if (response.redirected) {
191	        Logger.debug(`Runtime redirected to ${response.url}`);
192	        // strip /health from the URL, using URL parsing to handle query params
193	        const redirected = new URL(response.url);
194	        redirected.pathname = redirected.pathname.replace(/\/health$/, "");
195	        this.config.url = redirected.toString();
196	      }
197	
198	      const success = response.ok;
199	      if (success) {
200	        this.setDOMBaseUri(this.config.url);
201	      }
202	      return success;
203	    } catch (error) {
204	      Logger.error(
205	        `Failed to check health: ${error instanceof Error ? error.message : "Unknown error"}`,
206	        { cause: error },
207	      );
208	      return false;
209	    }
210	  }
