83	export type CloseDecision =
84	  | { kind: "terminal"; status: ConnectionStatus; closeTransport: boolean }
85	  | { kind: "gave-up"; status: ConnectionStatus }
86	  | { kind: "retry"; status: ConnectionStatus };
87	
88	export function classifyCloseEvent(
89	  event: { reason?: string },
90	  context: { retryCount: number; maxRetries: number },
91	): CloseDecision {
92	  switch (event.reason) {
93	    case "MARIMO_ALREADY_CONNECTED":
94	      return {
95	        kind: "terminal",
96	        status: {
97	          state: WebSocketState.CLOSED,
98	          code: WebSocketClosedReason.ALREADY_RUNNING,
99	          reason: "another browser tab is already connected to the kernel",
100	          canTakeover: true,
101	        },
102	        closeTransport: true,
103	      };
104	    case "MARIMO_WRONG_KERNEL_ID":
105	    case "MARIMO_NO_FILE_KEY":
106	    case "MARIMO_NO_SESSION_ID":
107	    case "MARIMO_NO_SESSION":
108	    case "MARIMO_SHUTDOWN":
109	      return {
110	        kind: "terminal",
111	        status: {
112	          state: WebSocketState.CLOSED,
113	          code: WebSocketClosedReason.KERNEL_DISCONNECTED,
114	          reason: "kernel not found",
115	        },
116	        closeTransport: true,
117	      };
118	    case "MARIMO_MALFORMED_QUERY":
119	      return {
120	        kind: "terminal",
121	        status: {
122	          state: WebSocketState.CLOSED,
123	          code: WebSocketClosedReason.MALFORMED_QUERY,
124	          reason:
125	            "the kernel did not recognize a request; please file a bug with marimo",
126	        },
127	        closeTransport: false,
128	      };
129	    case "MARIMO_KERNEL_STARTUP_ERROR":
130	      return {
131	        kind: "terminal",
132	        status: {
133	          state: WebSocketState.CLOSED,
134	          code: WebSocketClosedReason.KERNEL_STARTUP_ERROR,
135	          reason: "Failed to start kernel sandbox",
136	        },
137	        closeTransport: true,
138	      };
139	    default:
140	      // Empty/undefined reasons are normal transient closes. Anything else is
141	      // an unknown server reason; warn so a new MARIMO_* reason doesn't fall
142	      // silently into the retry path.
143	      if (event.reason) {
144	        logNever(event.reason as never);
145	      }
146	  }
147	  // partysocket stops retrying silently once `maxRetries` is hit; surface
148	  // CLOSED so callers can detect the give-up.
149	  if (context.retryCount >= context.maxRetries) {
150	    return {
151	      kind: "gave-up",
152	      status: {
153	        state: WebSocketState.CLOSED,
154	        code: WebSocketClosedReason.KERNEL_DISCONNECTED,
155	        reason: "kernel not found",
156	      },
157	    };
158	  }
159	  return {
160	    kind: "retry",
161	    status: { state: WebSocketState.CONNECTING },
162	  };
163	}
