import ReconnectingWebSocket from "partysocket/ws";
import {
  type ConnectionEvent,
  type ConnectionTransportCallback,
  type IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops retrying silently; the transport rewrites the close reason to
// TRANSPORT_EXHAUSTED_REASON so downstream classification can detect the
// give-up instead of treating it as a transient close.
export const MAX_RETRIES = 10;

// Synthetic close reason injected once the retry budget is exhausted. This is
// recognized by `classifyCloseEvent` as the terminal "gave-up" signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

/**
 * A WebSocket transport that wraps a reconnecting WebSocket.
 *
 * It intercepts close events: once the inner socket has exhausted its retry
 * budget (`retryCount >= MAX_RETRIES`), the close event's `reason` is rewritten
 * to {@link TRANSPORT_EXHAUSTED_REASON} before it is dispatched to registered
 * listeners. This rewrite applies even when the original close event carried a
 * server-sent reason. Below the budget, the original reason is forwarded
 * unchanged.
 */
export class WsTransport implements IConnectionTransport {
  readonly inner: ReconnectingWebSocket;

  // For each event type, map the caller's callback to the wrapper we actually
  // registered on the inner socket. This lets us (a) deduplicate registrations
  // of the same callback and (b) remove the exact wrapper on unregister so no
  // orphaned listeners are left behind on the inner socket.
  private listeners = new Map<
    ConnectionEvent,
    Map<
      ConnectionTransportCallback<ConnectionEvent>,
      ConnectionTransportCallback<ConnectionEvent>
    >
  >();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    let forEvent = this.listeners.get(event);
    if (!forEvent) {
      forEvent = new Map();
      this.listeners.set(event, forEvent);
    }

    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    // Deduplicate: registering the same callback more than once must not cause
    // it to fire more than once per event.
    if (forEvent.has(cb)) {
      return;
    }

    const wrapper: ConnectionTransportCallback<ConnectionEvent> =
      event === "close"
        ? (e) => cb(this.rewriteCloseEvent(e) as never)
        : (e) => cb(e);

    forEvent.set(cb, wrapper);
    this.inner.addEventListener(
      event as keyof WebSocketEventMap,
      wrapper as (e: Event) => void,
    );
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const forEvent = this.listeners.get(event);
    if (!forEvent) {
      return;
    }
    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    const wrapper = forEvent.get(cb);
    if (!wrapper) {
      return;
    }
    // A single call fully unregisters the callback: because registrations are
    // deduplicated, at most one wrapper exists per callback, so removing it
    // leaves no orphaned listeners on the inner socket.
    this.inner.removeEventListener(
      event as keyof WebSocketEventMap,
      wrapper as (e: Event) => void,
    );
    forEvent.delete(cb);
  }

  /**
   * Rewrite a close event's reason to {@link TRANSPORT_EXHAUSTED_REASON} once
   * the inner socket's retry budget is exhausted. Below the budget the event is
   * returned unchanged. When rewriting, we build a shallow event-like clone so
   * we don't mutate the original (read-only) CloseEvent; `code` and other
   * fields are preserved.
   */
  private rewriteCloseEvent(event: unknown): unknown {
    if (this.inner.retryCount < MAX_RETRIES) {
      return event;
    }

    const src = (event ?? {}) as Record<string, unknown>;
    return {
      ...src,
      type: src.type ?? "close",
      code: src.code,
      wasClean: src.wasClean,
      reason: TRANSPORT_EXHAUSTED_REASON,
    };
  }
