function makeTransport() {
  const t = new WsTransport(() => "ws://localhost/ws");
  // Replace inner with a controllable fake.
  const handlers: Record<string, Set<(e: unknown) => void>> = {};
  const fake = {
    retryCount: 0,
    readyState: 3,
    addEventListener: (ev: string, cb: (e: unknown) => void) => {
      (handlers[ev] ??= new Set()).add(cb);
    },
    removeEventListener: (ev: string, cb: (e: unknown) => void) => {
      handlers[ev]?.delete(cb);
    },
    emit: (ev: string, e: unknown) => {
      for (const cb of handlers[ev] ?? []) {
        cb(e);
      }
    },
    handlers,
  };
  (t as unknown as { inner: unknown }).inner = fake;
  return { t, fake };
}

describe("WsTransport verify", () => {
  it("exports constants", () => {
    expect(MAX_RETRIES).toBe(10);
    expect(TRANSPORT_EXHAUSTED_REASON).toBe("MARIMO_TRANSPORT_EXHAUSTED");
  });

  it("rewrites reason on exhaustion even with server reason", () => {
    const { t, fake } = makeTransport();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    fake.retryCount = MAX_RETRIES;
    fake.emit("close", { code: 1006, reason: "MARIMO_SHUTDOWN" });
