    expect(cb.mock.calls[0][0].reason).toBe(TRANSPORT_EXHAUSTED_REASON);
    expect(cb.mock.calls[0][0].code).toBe(1006);
  });

  it("forwards original reason below budget", () => {
    const { t, fake } = makeTransport();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    fake.retryCount = MAX_RETRIES - 1;
    fake.emit("close", { code: 1006, reason: "MARIMO_SHUTDOWN" });
    expect(cb.mock.calls[0][0].reason).toBe("MARIMO_SHUTDOWN");
  });

  it("dedupes registrations", () => {
    const { t, fake } = makeTransport();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    t.addEventListener("close", cb as never);
    t.addEventListener("close", cb as never);
    fake.emit("close", { code: 1006, reason: "" });
    expect(cb).toHaveBeenCalledTimes(1);
  });

  it("removes fully with single call, no orphaned listeners", () => {
    const { t, fake } = makeTransport();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    t.addEventListener("close", cb as never);
    t.removeEventListener("close", cb as never);
    expect(fake.handlers.close.size).toBe(0);
    fake.emit("close", { code: 1006, reason: "" });
    expect(cb).not.toHaveBeenCalled();
  });
});
